<form class="crm-card client-filters" method="get" action="<?= esc($filterAction) ?>"><div><label for="q">Search tasks</label><input id="q" name="q" class="form-control" maxlength="100" value="<?= esc($q) ?>" placeholder="Title or code"></div><div><label for="project_q">Find authorized projects</label><input id="project_q" name="project_q" class="form-control" maxlength="100" value="<?= esc($projectQuery) ?>" placeholder="Search then Apply filters"></div><div><label for="project">Project</label><select id="project" name="project" class="form-select"><option value="">All authorized projects</option><?php foreach($projects as $item): ?><option value="<?= (int)$item['id'] ?>" <?= $project===(int)$item['id']?'selected':'' ?>><?= esc($item['name']) ?></option><?php endforeach ?></select></div><?php foreach(['status'=>['Status',$statuses],'priority'=>['Priority',$priorities]] as $key=>[$label,$items]): ?><div><label for="<?= $key ?>"><?= $label ?></label><select id="<?= $key ?>" name="<?= $key ?>" class="form-select"><option value="">All</option><?php foreach($items as $item): ?><option value="<?= (int)$item['id'] ?>" <?= $$key===(int)$item['id']?'selected':'' ?>><?= esc($item['name']) ?></option><?php endforeach ?></select></div><?php endforeach ?><div><label for="assignee_q">Find scoped assignees</label><input id="assignee_q" name="assignee_q" class="form-control" maxlength="60" value="<?= esc($assigneeQuery) ?>"></div><div><label for="assignee">Assignee</label><select id="assignee" name="assignee" class="form-select"><option value="">All</option><?php foreach($assignees as $item): ?><option value="<?= (int)$item['id'] ?>" <?= $assignee===(int)$item['id']?'selected':'' ?>><?= esc($item['username']) ?></option><?php endforeach ?></select></div><div><label for="archive">Records</label><select class="form-select" id="archive" name="archive"><option value="active" <?= $archive==='active'?'selected':'' ?>>Unarchived</option><option value="archived" <?= $archive==='archived'?'selected':'' ?>>Archived (authorized managers)</option></select></div><div class="client-actions"><button type="submit" class="btn btn-teal">Apply filters</button><a class="btn btn-outline-light" href="<?= esc($filterAction) ?>">Reset</a></div></form>
